class Raven < Formula
  desc "Windows compatibility layer: run Windows programs as native CPU code on Linux"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  url "https://github.com/qzmfranklin/homebrew-tap/releases/download/raven-0.1.0/raven-0.1.0-linux-amd64.tar.xz"
  version "0.1.0"
  sha256 "ee57d5486146a0a6a487e8242e4607457f307fe4566369c5d7421b110ef053b2"
  license :cannot_represent
  depends_on arch: :x86_64

  # Linux-only formula (rules_brew plan 0006 rows 6.4/6.8,
  # the row-6.10 amendment): the :linux requirement owns the
  # mac refusal -- never a readall-fatal raise.
  depends_on :linux

  def install
    # The beside-binary layout (raven 0002-02 row 2.2): the loader probes every
    # runtime component against /proc/self/exe's OWN directory (the sandbox maps
    # the Windows system directory onto the exe dir — native/nt/paths.cpp; the
    # 32-bit set + comctl32 in x86/ beside it — x86_loader.cpp; fonts/ and
    # roots/ probed the same way), so the whole extracted tree lands at the KEG
    # root — visible as <opt>/raven/... — and bin/raven is a SYMLINK into it,
    # never a copy (a copy in bin/ would sit beside nothing and the loader
    # would find no components).
    prefix.install Dir["*"]
    bin.install_symlink prefix/"raven"
    # The tar's members land 0644 (the pkg_files pipeline does not carry the
    # genrule outputs' exec bits — the same defect surf's install hit; a tar
    # SHOULD preserve modes, so the durable fix belongs at the packaging
    # layer, recorded in plan 0002-02), and BOTH executables matter: raven
    # itself (every invocation) and raven-bootstrap, which the loader fork/execl
    # s beside the binary (native_cpu.cpp:156 — a 0644 bootstrap dies as exit
    # 127 and every --run-process reports "native bootstrap did not stop after
    # exec", the exact failure the first e2e run caught). The published 0.1.0
    # bytes are immutable, so the formula re-chmods — the surf precedent.
    chmod 0755, prefix/"raven"
    chmod 0755, prefix/"raven-bootstrap"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"raven"
      system "/usr/bin/xattr", "-cr", bin/"raven"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"raven"
    end
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/raven"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew raven at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed raven is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"raven") unless linked.symlink?
  end


  def caveats
